package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.MathArrays;
import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link DiscreteDistribution#sample(int)}.
 */
public class DiscreteDistribution_sample_TriageGen2Test {

    private List<Pair<String, Double>> sampleData;
    private DiscreteDistribution<String> distribution;

    @Before
    public void setUp() {
        sampleData = Arrays.asList(
            new Pair<>("A", 0.2),
            new Pair<>("B", 0.5),
            new Pair<>("C", 0.3)
        );
        distribution = new DiscreteDistribution<>(sampleData);
    }

    @Test
    public void testSample_PositiveSize_ReturnsCorrectArraySize() {
        int sampleSize = 5;
        String[] result = distribution.sample(sampleSize);

        assertNotNull(result);
        assertEquals(sampleSize, result.length);
    }

    @Test
    public void testSample_PositiveSize_ContainsValidElements() {
        int sampleSize = 10;
        String[] result = distribution.sample(sampleSize);

        List<String> validOptions = Arrays.asList("A", "B", "C");
        for (String element : result) {
            assertTrue("Sampled element should be one of the input samples", 
                validOptions.contains(element));
        }
    }

    @Test
    public void testSample_ZeroSize_ThrowsNotStrictlyPositiveException() {
        int sampleSize = 0;
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(sampleSize);
        });
    }

    @Test
    public void testSample_NegativeSize_ThrowsNotStrictlyPositiveException() {
        int sampleSize = -1;
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(sampleSize);
        });
    }

    @Test
    public void testSample_LargeSize_ReturnsCorrectArraySize() {
        int sampleSize = 100;
        String[] result = distribution.sample(sampleSize);
        assertEquals(sampleSize, result.length);
    }
}
